<?php
declare(strict_types=1); require __DIR__.'/../config/config.php'; require_role(['pharmacist','manager','admin']);
function h($v){return htmlspecialchars((string)($v??''),ENT_QUOTES,'UTF-8');}
function importRows(string $path,string $ext):array{if($ext==='csv'){$fh=fopen($path,'rb');if(!$fh)throw new RuntimeException('Unable to read CSV.');$headers=fgetcsv($fh);if(!$headers)throw new RuntimeException('CSV is empty.');$headers=array_map(fn($x)=>strtolower(trim((string)$x)),$headers);$rows=[];while(($r=fgetcsv($fh))!==false){if(count(array_filter($r,fn($x)=>trim((string)$x)!==''))===0)continue;$row=[];foreach($headers as $i=>$key)$row[$key]=trim((string)($r[$i]??''));$rows[]=$row;}fclose($fh);return $rows;}if($ext!=='xlsx'||!class_exists('ZipArchive'))throw new RuntimeException('Excel import requires an .xlsx file and PHP ZipArchive extension.');$zip=new ZipArchive();if($zip->open($path)!==true)throw new RuntimeException('Unable to open Excel file.');$shared=[];$xml=$zip->getFromName('xl/sharedStrings.xml');if($xml!==false){$sx=simplexml_load_string($xml);foreach($sx->si as $si)$shared[]=(string)implode('',array_map('strval',$si->xpath('.//t')));}$sheet=$zip->getFromName('xl/worksheets/sheet1.xml');if($sheet===false)throw new RuntimeException('Excel sheet 1 not found.');$sx=simplexml_load_string($sheet);$rows=[];foreach($sx->sheetData->row as $rr){$vals=[];foreach($rr->c as $c){$ref=(string)$c['r'];preg_match('/([A-Z]+)/',$ref,$m);$col=0;foreach(str_split($m[1]) as $ch)$col=$col*26+(ord($ch)-64);$col--;$v=(string)$c->v;if((string)$c['t']==='s')$v=$shared[(int)$v]??'';$vals[$col]=$v;}$rows[]=$vals;}$zip->close();if(!$rows)return [];$headers=[];foreach($rows[0] as $k=>$v)$headers[$k]=strtolower(trim((string)$v));$out=[];foreach(array_slice($rows,1) as $r){$row=[];foreach($headers as $i=>$key)$row[$key]=trim((string)($r[$i]??''));if(count(array_filter($row,fn($x)=>$x!==''))>0)$out[]=$row;}return $out;}
$columns=['name','generic_name','strength','manufacturer','barcode','unit_name','units_per_strip','strips_per_box','purchase_price','retail_unit_price','reorder_level','min_profit_margin_pct'];
if(isset($_GET['download_template'])){header('Content-Type:text/csv; charset=utf-8');header('Content-Disposition:attachment; filename=medicines_template.csv');$fh=fopen('php://output','wb');fputcsv($fh,$columns);fputcsv($fh,['Demo Paracetamol','Paracetamol','500mg','Demo Manufacturer','100000000001','tablet',10,10,4,5,20,10]);fclose($fh);exit;}
if($_SERVER['REQUEST_METHOD']==='POST'){$pdo=db();$action=$_POST['action']??'';try{if($action==='bulk_save'){$rows=json_decode($_POST['rows']??'[]',true)?:[];if(!$rows)throw new RuntimeException('Add at least one medicine.');$pdo->beginTransaction();$insert=$pdo->prepare('INSERT INTO medicines(name,generic_name,strength,manufacturer,barcode,unit_name,units_per_strip,strips_per_box,purchase_price,retail_unit_price,reorder_level,min_profit_margin_pct) VALUES(?,?,?,?,?,?,?,?,?,?,?,?)');$n=0;foreach($rows as $r){$name=trim((string)($r['name']??''));if($name==='')continue;$barcode=trim((string)($r['barcode']??''));if($barcode!==''){$q=$pdo->prepare('SELECT id FROM medicines WHERE barcode=?');$q->execute([$barcode]);if($q->fetch())throw new RuntimeException('Barcode already exists: '.$barcode);}$insert->execute([$name,trim((string)($r['generic_name']??''))?:null,trim((string)($r['strength']??''))?:null,trim((string)($r['manufacturer']??''))?:null,$barcode?:null,trim((string)($r['unit_name']??'tablet'))?:'tablet',max(1,(int)($r['units_per_strip']??1)),max(1,(int)($r['strips_per_box']??1)),max(0,(float)($r['purchase_price']??0)),max(0,(float)($r['retail_unit_price']??0)),max(0,(int)($r['reorder_level']??0)),min(100,max(0,(float)($r['min_profit_margin_pct']??10)))]);$n++;}$pdo->commit();audit_log('bulk_medicines_created',$n.' medicines created');header('Location: medicines.php?saved='.$n);exit;}if($action==='import'){if(empty($_FILES['file']['tmp_name']))throw new RuntimeException('Choose a CSV or XLSX file.');$ext=strtolower(pathinfo($_FILES['file']['name'],PATHINFO_EXTENSION));$rows=importRows($_FILES['file']['tmp_name'],$ext);if(!$rows)throw new RuntimeException('No data rows found.');$pdo->beginTransaction();$insert=$pdo->prepare('INSERT INTO medicines(name,generic_name,strength,manufacturer,barcode,unit_name,units_per_strip,strips_per_box,purchase_price,retail_unit_price,reorder_level,min_profit_margin_pct) VALUES(?,?,?,?,?,?,?,?,?,?,?,?)');$n=0;foreach($rows as $r){$name=trim((string)($r['name']??''));if($name==='')continue;$barcode=trim((string)($r['barcode']??''));if($barcode!==''){$q=$pdo->prepare('SELECT id FROM medicines WHERE barcode=?');$q->execute([$barcode]);if($q->fetch())continue;}$insert->execute([$name,trim((string)($r['generic_name']??''))?:null,trim((string)($r['strength']??''))?:null,trim((string)($r['manufacturer']??''))?:null,$barcode?:null,trim((string)($r['unit_name']??'tablet'))?:'tablet',max(1,(int)($r['units_per_strip']??1)),max(1,(int)($r['strips_per_box']??1)),max(0,(float)($r['purchase_price']??0)),max(0,(float)($r['retail_unit_price']??0)),max(0,(int)($r['reorder_level']??0)),min(100,max(0,(float)($r['min_profit_margin_pct']??10)))]);$n++;}$pdo->commit();audit_log('medicines_imported',$n.' medicines imported');header('Location: medicines.php?imported='.$n);exit;}}catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();$error=$e->getMessage();}}
$rows=db()->query('SELECT m.*,COALESCE(SUM(b.units_remaining),0) stock FROM medicines m LEFT JOIN batches b ON b.medicine_id=m.id WHERE m.active=1 GROUP BY m.id ORDER BY m.name')->fetchAll();
?><!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Medicines · <?=h(APP_NAME)?></title><link rel="stylesheet" href="style.css"><style>.bulk-table{overflow:auto}.bulk-table table{min-width:1100px}.bulk-table input{min-width:105px}.bulk-actions{display:flex;gap:10px;align-items:center;flex-wrap:wrap}.import-help{font-size:13px;color:#718096}</style></head><body><header><div class="brand">💊 <?=h(APP_NAME)?></div><nav><a href="index.php">Dashboard</a><a href="pos.php">POS</a><a class="active" href="manage.php">Management</a></nav><div class="user-info">👤 <?=h(current_user()['username']??'')?> · <?=h(ucfirst(current_user()['role']??''))?> · <a href="logout.php">Logout</a></div></header><main><div class="page-title"><div><div class="eyebrow">CATALOGUE</div><h1>Medicines</h1><p>Add many medicines at once or import a CSV/XLSX file.</p></div></div><?php if(isset($_GET['saved'])):?><div class="success">✓ <?=h($_GET['saved'])?> medicines saved.</div><?php endif;?><?php if(isset($_GET['imported'])):?><div class="success">✓ <?=h($_GET['imported'])?> medicines imported. Existing barcodes were skipped.</div><?php endif;?><?php if(isset($error)):?><div class="error">✕ <?=h($error)?></div><?php endif;?><section class="panel"><h2>Bulk Add Medicines</h2><div class="bulk-table"><table id="bulk"><thead><tr><th>Name *</th><th>Generic</th><th>Strength</th><th>Manufacturer</th><th>Barcode</th><th>Unit</th><th>Tabs/Strip</th><th>Strips/Box</th><th>Purchase/Tab</th><th>Retail/Tab *</th><th>Reorder</th><th>Min Margin %</th><th></th></tr></thead><tbody></tbody></table></div><div class="bulk-actions" style="margin-top:14px"><button type="button" class="btn" id="addRow">＋ Add Row</button><button type="button" class="btn" id="saveAll">💾 Save All Medicines</button></div></section><section class="panel"><h2>CSV / Excel Import</h2><form method="post" enctype="multipart/form-data" class="grid"><input type="hidden" name="action" value="import"><label>CSV or Excel (.xlsx)<input type="file" name="file" accept=".csv,.xlsx" required></label><button class="btn">⬆ Import Medicines</button></form><p class="import-help">Required column: <b>name</b>. Optional columns: generic_name, strength, manufacturer, barcode, unit_name, units_per_strip, strips_per_box, purchase_price, retail_unit_price, reorder_level, min_profit_margin_pct. Excel uses the first worksheet.</p><a href="medicines.php?download_template=1">Download CSV template</a></section><section class="panel"><h2>Current Medicines (<?=count($rows)?>)</h2><div class="bulk-table"><table><tr><th>Medicine</th><th>Manufacturer</th><th>Pack</th><th>Retail/Tab</th><th>Stock</th></tr><?php foreach($rows as $r):?><tr><td><b><?=h($r['name'])?></b><small><?=h($r['generic_name'])?> <?=h($r['strength'])?></small></td><td><?=h($r['manufacturer'])?></td><td><?=$r['units_per_strip']?> tabs/strip × <?=$r['strips_per_box']?> strips/box</td><td>Rs. <?=money($r['retail_unit_price'])?></td><td><?=number_format((int)$r['stock'])?> tabs</td></tr><?php endforeach;?></table></div></section></main><script>const cols=<?=json_encode($columns)?>;const body=document.querySelector('#bulk tbody');function addRow(v={}){const tr=document.createElement('tr');tr.innerHTML=cols.map(c=>'<td><input data-col="'+c+'" value="'+String(v[c]??(c==='unit_name'?'tablet':c==='units_per_strip'?10:c==='strips_per_box'?10:c==='reorder_level'?20:c==='min_profit_margin_pct'?10:0)).replace(/&/g,'&amp;').replace(/"/g,'&quot;')+'"></td>').join('')+'<td><button type="button" class="btn" onclick="this.closest(\'tr\').remove()">×</button></td>';body.appendChild(tr);}function collect(){return [...body.querySelectorAll('tr')].map(tr=>{const o={};tr.querySelectorAll('[data-col]').forEach(i=>o[i.dataset.col]=i.value);return o;}).filter(x=>x.name.trim()!=='');}addRow();addRow();document.getElementById('addRow').onclick=()=>addRow();document.getElementById('saveAll').onclick=()=>{const rows=collect();if(!rows.length){alert('Add at least one medicine.');return;}const f=document.createElement('form');f.method='post';f.action='medicines.php';f.innerHTML='<input name="action" value="bulk_save"><input name="rows">';f.querySelector('[name=rows]').value=JSON.stringify(rows);document.body.appendChild(f);f.submit();};</script></body></html>